/* EXTRAS — NCERT tables, activities and diagrams per chapter */
window.EXTRAS = window.EXTRAS || {};

window.EXTRAS['che1'] = {
  acts: [
    { n: '1.1', aim: 'Burning a magnesium ribbon', steps: ['Clean a magnesium ribbon 3-4 cm long by rubbing it with sandpaper.', 'Hold it with a pair of tongs and burn it using a spirit lamp or burner.', 'Collect the ash formed in a watch-glass.'], obs: 'Magnesium burns with a dazzling white flame and leaves a white ash (magnesium oxide).', con: '2Mg + O\u2082 \u2192 2MgO — a combination reaction; the white powder is basic in nature.' },
    { n: '1.2', aim: 'Zinc granules with dilute sulphuric acid', steps: ['Take a few zinc granules in a conical flask.', 'Add dilute sulphuric acid through a thistle funnel.', 'Pass the gas through a soap solution and bring a burning candle near the bubbles.'], obs: 'Bubbles rise from the granules; the soap bubbles burn with a pop sound.', con: 'Zn + H\u2082SO\u2084 \u2192 ZnSO\u2084 + H\u2082 — displacement; hydrogen gas is evolved.' },
    { n: '1.3', aim: 'Heating ferrous sulphate crystals', steps: ['Take about 2 g of ferrous sulphate crystals in a dry boiling tube.', 'Note the colour; heat the tube over a burner flame.'], obs: 'The green crystals first lose water; a smell of burning sulphur follows; a red-brown residue remains.', con: '2FeSO\u2084 \u2192 Fe\u2082O\u2083 + SO\u2082 + SO\u2083 — thermal decomposition.' },
    { n: '1.4', aim: 'Silver chloride in sunlight', steps: ['Take about 2 g of silver chloride in a china dish.', 'Keep it in sunlight for some time and observe.'], obs: 'White silver chloride slowly turns grey.', con: '2AgCl \u2192 2Ag + Cl\u2082 — photolytic decomposition, used in black-and-white photography.' },
    { n: '1.5', aim: 'Electrolysis of water', steps: ['Take a plastic mug with water and a few drops of dilute sulphuric acid; fit two test tubes full of water over two carbon electrodes.', 'Pass electricity through the circuit for some time.', 'Test both gases with a burning splinter.'], obs: 'Bubbles fill both tubes — twice as much gas at one electrode as the other. One gas burns with a pop, the other relights a glowing splinter.', con: '2H\u2082O \u2192 2H\u2082 + O\u2082 — electrolytic decomposition; H\u2082 at cathode (double volume), O\u2082 at anode.' },
    { n: '1.6', aim: 'Iron nail in copper sulphate solution', steps: ['Take a clean iron nail and a copper sulphate solution in a beaker.', 'Keep the nail dipped for about 20 minutes and observe.'], obs: 'The blue colour fades to light green and a brown coating deposits on the nail.', con: 'Fe + CuSO\u2084 \u2192 FeSO\u2084 + Cu — displacement; iron is more reactive than copper.' },
    { n: '1.7', aim: 'Sodium sulphate with barium chloride', steps: ['Take about 3 mL of sodium sulphate solution in a test tube.', 'Add 5 mL of barium chloride solution and observe.'], obs: 'A white insoluble substance (precipitate) settles at the bottom.', con: 'Na\u2082SO\u2084 + BaCl\u2082 \u2192 BaSO\u2084\u2193 + 2NaCl — double displacement (precipitation).' },
    { n: '1.8', aim: 'Copper oxide heated with hydrogen', steps: ['Pass hydrogen gas over hot copper oxide in a combustion tube.', 'Collect and test the colourless liquid formed.'], obs: 'Black copper oxide turns reddish-brown; droplets of a colourless liquid collect.', con: 'CuO + H\u2082 \u2192 Cu + H\u2082O — CuO is reduced, H\u2082 is oxidised: a redox reaction.' }
  ]
};

